from itertools import combinations
from pathlib import Path
import z3,json,time
n=11
trs=list(combinations(range(n),3));tets=list(combinations(range(n),4))
x={t:z3.Bool('t'+''.join(map(str,t))) for t in trs}; y={t:z3.Bool('q'+''.join(map(str,t))) for t in tets}
s=z3.Solver();s.set(timeout=110000)
for t in trs:
    co=[y[q] for q in tets if set(t)<=set(q)]
    s.add(z3.If(x[t],z3.Sum([z3.If(b,1,0) for b in co])==2,z3.Sum([z3.If(b,1,0) for b in co])==0))
for q in tets:
    ts=[x[t] for t in combinations(q,3)]
    s.add(z3.Implies(z3.Sum([z3.If(b,1,0) for b in ts])>=3,y[q]))
for v in range(n):s.add(z3.Sum([z3.If(y[q],1,0) for q in tets if v in q])==2*n-6)
cycle=list(range(3,11));linktris=set()
for a in (1,2):
    for i in range(len(cycle)):linktris.add(tuple(sorted((a,cycle[i],cycle[(i+1)%len(cycle)]))))
for q in tets:
    if 0 in q:s.add(y[q]==(tuple(v for v in q if v!=0) in linktris))
print('start',flush=True);ans=s.check();print(ans,flush=True)
if ans==z3.sat:
    m=s.model();fs=[q for q in tets if z3.is_true(m[y[q]])];print(fs)
    Path('workspace/agent3_localflag11.json').write_text(json.dumps(fs))

